void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float speed = 20.; //speed at which noise updates
    float zoom = 2.; //noise texture zoom
    vec2 uv = fragCoord/iResolution.xy;
    vec4 color = texture(iChannel0, uv);
    float dither = texture(iChannel2, (fragCoord+vec2(round(iTime*speed)*iChannelResolution[2].xy/2.))/(iChannelResolution[2].xy*zoom)).x;
    fragColor = color + vec4(vec3(dither/10.), 1.);
}
